// @vitest-environment jsdom
// A model-written set (ADR-028 section 8): the host-owned "AI-generated by <model>. It can be
// wrong." text above the frame, always visible and not dismissible; the frame's accessible name
// starts with "AI-generated"; body sets add the safety sentence; "This looks wrong" is offered
// for quiz and teaser sets only and stores a skip without sending anything.

import { act, createRef, type MutableRefObject } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const calls: { command: string; args?: Record<string, unknown> }[] = [];

vi.mock("@tauri-apps/api/core", () => ({
  invoke: (command: string, args?: Record<string, unknown>) => {
    calls.push({ command, args });
    switch (command) {
      case "activity_snapshot":
        return Promise.resolve(null);
      case "activity_content":
        return Promise.resolve({ title: "x", questions: [] });
      case "activity_launch":
        return Promise.resolve("lullact://localhost/key/set/index.html");
      case "activity_launch_end":
        return Promise.resolve(null);
      case "generated_set_items":
        return Promise.resolve(["First question?", "Second question?", "Third question?"]);
      case "generated_set_skip":
        return Promise.resolve(null);
      default:
        return Promise.reject(new Error("unavailable"));
    }
  },
  Channel: class {},
}));

import { ActivityHost, type ActivityInfo, type HostControl } from "./ActivityHost";
import { click, polyfillDialog, settle } from "../companion/testDom";

polyfillDialog();

const set = (
  over: Partial<ActivityInfo> = {},
  model: string | null = "gpt-test",
): ActivityInfo => ({
  id: "lullshift.generated.quiz.abcdefghij12",
  name: "Ocean quiz",
  description: "Written for you by your own model. It can be wrong.",
  category: "interactive",
  version: "0.1.0",
  storage: false,
  savedUtc: null,
  help: null,
  preview: false,
  playedSeconds: 0,
  engine: "lullshift.quiz@1",
  source: { marketplaceId: "generated", builtin: false, commit: null },
  generated: {
    model,
    engine: "lullshift.quiz@1",
    createdUtc: "2026-11-08T10:00:00Z",
    topic: "The ocean",
    difficulty: "medium",
    unusable: false,
  },
  ...over,
});

let host: HTMLDivElement;
let root: Root;
let control: MutableRefObject<HostControl | null>;

const render = (activity: ActivityInfo) =>
  act(async () => {
    root.render(
      <ActivityHost
        activity={activity}
        active
        pause={null}
        controlRef={control}
        onClose={() => undefined}
        onGoToSessions={() => undefined}
      />,
    );
  });

beforeEach(() => {
  calls.length = 0;
  control = createRef<HostControl | null>() as MutableRefObject<HostControl | null>;
  host = document.createElement("div");
  document.body.append(host);
  root = createRoot(host);
});
afterEach(() => {
  act(() => root.unmount());
  host.remove();
});

const notice = () => host.querySelector('[data-testid="ai-notice"]');
const buttons = () => [...host.querySelectorAll("button")].map((b) => b.textContent?.trim());

describe("the AI-generated label", () => {
  it("shows the model's name above the frame, as page text, and starts the frame's name with AI-generated", async () => {
    await render(set());
    await settle();
    expect(notice()?.textContent).toContain("AI-generated by gpt-test. It can be wrong.");
    expect(notice()?.textContent).not.toContain("Stop if anything feels uncomfortable");
    // In the page itself (not a tooltip), before the stage that holds the frame.
    const stage = host.querySelector(".host-stage")!;
    expect(
      notice()!.compareDocumentPosition(stage) & Node.DOCUMENT_POSITION_FOLLOWING,
    ).toBeTruthy();
    expect(notice()?.hasAttribute("title")).toBe(false);
    // There is nothing to dismiss it with.
    expect(notice()!.querySelector("[aria-label*='ismiss']")).toBeNull();
    const frame = host.querySelector("iframe");
    expect(frame?.getAttribute("title")?.startsWith("AI-generated")).toBe(true);
    expect(host.querySelector("section.host")?.getAttribute("aria-label")).toMatch(/^AI-generated/);
  });

  it("says 'your model' when the name is unknown, and cuts a long name", async () => {
    await render(set({}, null));
    await settle();
    expect(notice()?.textContent).toContain("AI-generated by your model. It can be wrong.");
    await render(set({}, "m".repeat(80)));
    await settle();
    const text = notice()?.textContent ?? "";
    expect(text).toContain(`AI-generated by ${"m".repeat(40)}. It can`);
    expect(text).not.toContain("m".repeat(41));
  });

  it("renders the model name as plain text, never as markup", async () => {
    await render(set({}, "<img src=x onerror=alert(1)>"));
    await settle();
    expect(notice()?.querySelector("img")).toBeNull();
    expect(notice()?.textContent).toContain("<img src=x");
  });

  it("adds the safety sentence for body sets, and shows nothing for other activities", async () => {
    const body = set({
      engine: "lullshift.movement@1",
      generated: { ...set().generated!, engine: "lullshift.movement@1" },
    });
    await render(body);
    await settle();
    expect(notice()?.textContent).toContain("Stop if anything feels uncomfortable.");
    await render({ ...set(), generated: null, name: "Plain", id: "plain.one" });
    await settle();
    expect(notice()).toBeNull();
    expect(host.querySelector("iframe")?.getAttribute("title")).toBe("Plain");
  });

  it("stays visible in the paused view, which carries the tag too", async () => {
    await render(set());
    await settle();
    await act(async () => {
      await control.current!.pauseNow();
    });
    await settle();
    expect(notice()).not.toBeNull();
    expect(host.querySelector(".host-card [data-testid='ai-tag']")?.textContent).toBe(
      "AI-generated · gpt-test",
    );
  });
});

describe("This looks wrong", () => {
  it("is offered for quiz and teaser sets only", async () => {
    await render(set());
    await settle();
    expect(buttons()).toContain("This looks wrong");
    await render(
      set({
        engine: "lullshift.teaser@1",
        generated: { ...set().generated!, engine: "lullshift.teaser@1" },
      }),
    );
    await settle();
    expect(buttons()).toContain("This looks wrong");
    await render(
      set({
        engine: "lullshift.cards@1",
        generated: { ...set().generated!, engine: "lullshift.cards@1" },
      }),
    );
    await settle();
    expect(buttons()).not.toContain("This looks wrong");
  });

  it("lets the user pick an item, stores the skip locally and sends nothing anywhere", async () => {
    await render(set());
    await settle();
    const open = [...host.querySelectorAll("button")].find(
      (b) => b.textContent?.trim() === "This looks wrong",
    )!;
    await click(open);
    const dialog = document.querySelector<HTMLDialogElement>("dialog[open]")!;
    expect(dialog.textContent).toContain("nothing is sent");
    const items = [...dialog.querySelectorAll("label")].map((l) => l.textContent);
    expect(items).toEqual(["First question?", "Second question?", "Third question?"]);
    const leave = [...dialog.querySelectorAll("button")].find(
      (b) => b.textContent === "Leave it out",
    )!;
    expect(leave.disabled).toBe(true);
    await click(dialog.querySelectorAll<HTMLInputElement>("input[type=radio]")[1]!);
    expect(leave.disabled).toBe(false);
    await click(leave);
    const skip = calls.find((c) => c.command === "generated_set_skip");
    expect(skip?.args).toEqual({ id: "lullshift.generated.quiz.abcdefghij12", itemIndex: 1 });
    expect(dialog.textContent).toContain("left out the next time this set starts");
    // Only host commands were used: nothing named for a provider or the Companion.
    expect(calls.some((c) => c.command.startsWith("companion_"))).toBe(false);
    expect(calls.some((c) => c.command === "generate_set")).toBe(false);
  });
});
